input.command:
cat > ~/.claude/settings.json <<'EOF'
{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [{ "type": "command", "command": "/home/runner/src/bin/dippy-hook" }]
      }
    ]
  }
}
EOF
python3 -m json.tool ~/.claude/settings.json >/dev/null && echo ok; ls -l /home/runner/src/bin/dippy-hook

